import{_ as a,o as e,c as r,a6 as o}from"./chunks/framework.De615z8S.js";const m=JSON.parse('{"title":"跨境出图：从商品事实到渠道交付","description":"","frontmatter":{"id":"cross-border","title":"跨境出图：从商品事实到渠道交付","chapter":"03","topic":"cross-border","status":"已公开","evidence_status":"原创教程与规划示范，尚未执行图像任务或后台上传","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["ecommerce-skills","footwear-skills","cross-border-knowledge","visual-copywriting"],"platform_rule_ids":["amazon","shopify","shopee"],"order":23},"headers":[],"relativePath":"ecommerce/cross-border.md","filePath":"ecommerce/cross-border.md"}'),d={name:"ecommerce/cross-border.md"};function i(s,t,h,c,n,l){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="跨境出图-从商品事实到渠道交付" tabindex="-1">跨境出图：从商品事实到渠道交付 <a class="header-anchor" href="#跨境出图-从商品事实到渠道交付" aria-label="Permalink to &quot;跨境出图：从商品事实到渠道交付&quot;">​</a></h1><p>一套跨境图片先固定商品事实，再按市场、图片位置和语言安排表达。Amazon主图负责真实识别，副图和A+负责解释；Shopify还要适配主题裁切，Shopee需要按市场整理封面、规格与变体。先完成一条商品链路，再扩大SKU。</p><h2 id="这次练习准备什么" tabindex="-1">这次练习准备什么 <a class="header-anchor" href="#这次练习准备什么" aria-label="Permalink to &quot;这次练习准备什么&quot;">​</a></h2><p>以下所有DN01、DN02名称和参数均为虚构练习数据，用来示范怎么填写任务；正式商品须替换为自己的真实记录。练习未附商品照片，也未执行生图。</p><table tabindex="0"><thead><tr><th>字段</th><th>DN01练习数据</th></tr></thead><tbody><tr><td>商品</td><td>带盖桌面收纳盒，虚构练习名DeskNest</td></tr><tr><td>外尺寸</td><td>长220 × 宽150 × 高120 mm</td></tr><tr><td>颜色与材质</td><td>白色；ABS，练习设定</td></tr><tr><td>已知结构</td><td>一个可拆隔板、一个盖子</td></tr><tr><td>发货内容</td><td>盒体1、盖子1、隔板1；不包括场景道具</td></tr><tr><td>获准场景</td><td>书桌收纳文具</td></tr><tr><td>未知项</td><td>容积、耐温、承重、防水、食品接触、认证、回收属性均未知</td></tr><tr><td>实拍需求</td><td>正面、顶部、开盖、隔板、侧面；未提供的角度不凭空补</td></tr></tbody></table><p>把真实素材按“对象照片、风格参考、准确文案、尺寸记录”四类整理。参考图只借用背景或布局；商品照片承担外观依据，规格来自记录。复制<a href="/ai-visual-creation-handbook/prompts/P09">P09跨境简报</a>，先生成渠道任务表。</p><h2 id="第1步-建立渠道矩阵" tabindex="-1">第1步：建立渠道矩阵 <a class="header-anchor" href="#第1步-建立渠道矩阵" aria-label="Permalink to &quot;第1步：建立渠道矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>任务</th><th>母版职责</th><th>后续动作</th></tr></thead><tbody><tr><td>Amazon US主图</td><td>只展示实际发货商品</td><td>检查类目规则、白底、占幅与实际像素</td></tr><tr><td>Amazon US副图</td><td>场景、结构、尺寸、配件、使用</td><td>每张只解决一个买家问题</td></tr><tr><td>Amazon A+</td><td>按实际模块组织图像与文字</td><td>用模块提示确定尺寸，手机预览</td></tr><tr><td>Shopify商品媒体</td><td>多角度与细节解释</td><td>排顺序、写alt text、看主题裁切</td></tr><tr><td>Shopify首页横幅</td><td>主题表达与商品引导</td><td>桌面和手机分别重排构图</td></tr><tr><td>Shopee SG</td><td>清晰封面、规格与变体</td><td>按当地后台检查上传参数</td></tr></tbody></table><p>这张表是练习任务分配，不规定每个渠道必须上传固定张数。<a href="/ai-visual-creation-handbook/resources/">平台资料卡</a>集中保留官方来源与适用范围；1024、2048等数字要区分官方建议、当前限制和练习母版。</p><h2 id="第2步-先做一张真实主体母版" tabindex="-1">第2步：先做一张真实主体母版 <a class="header-anchor" href="#第2步-先做一张真实主体母版" aria-label="Permalink to &quot;第2步：先做一张真实主体母版&quot;">​</a></h2><p>选清晰正面或45度实拍，在图层软件抠出主体。原照片、蒙版和商品层保留，记录允许修改的是背景、接触阴影和文案层。没有实拍时可以继续准备简报与版式，不把概念图写成正式商品图。</p><p>先按<a href="/ai-visual-creation-handbook/ecommerce/amazon-listing">Amazon主图教程</a>完成白底任务，再用同一真实主体建立场景图。模型容易改商品时，只生成背景，在PS／Krita里合成真实主体。检查商品颜色、盖子、隔板与数量后，再扩展其他图。</p><h2 id="第3步-按位置组织信息" tabindex="-1">第3步：按位置组织信息 <a class="header-anchor" href="#第3步-按位置组织信息" aria-label="Permalink to &quot;第3步：按位置组织信息&quot;">​</a></h2><p>副图不要每张重复同一句卖点。DN01可分成桌面场景、开盖结构、外尺寸、发货内容和使用顺序；“耐高温”“大容量”等未知事实不填。使用<a href="/ai-visual-creation-handbook/prompts/P11">P11副图分工</a>获得逐张构图和完整任务词。</p><p><a href="/ai-visual-creation-handbook/ecommerce/amazon-a-plus">A+教程</a>把结构、规格和使用拆模块；<a href="/ai-visual-creation-handbook/ecommerce/shopify-product">Shopify产品页</a>把相同事实整理成媒体序列；<a href="/ai-visual-creation-handbook/ecommerce/shopee-localization">Shopee教程</a>明确市场与变体。准确文字优先用可编辑图层，不反复让整图模型改小字。</p><h2 id="第4步-本地化、sku与交付" tabindex="-1">第4步：本地化、SKU与交付 <a class="header-anchor" href="#第4步-本地化、sku与交付" aria-label="Permalink to &quot;第4步：本地化、SKU与交付&quot;">​</a></h2><p>先做好一份事实母表，再制作英文或日文版本。场景和表达可调整，商品尺寸、配件和功能不能随市场变化。使用<a href="/ai-visual-creation-handbook/ecommerce/localization">本地化与单位教程</a>，再按<a href="/ai-visual-creation-handbook/ecommerce/cross-border-sku-delivery">SKU交付教程</a>建立文件清单。</p><p>最终交付包含：任务表、准确文案、图片、源文件状态、实际像素、检查结果和未完成项。网页上传成功、文字准确、源文件可编辑分别检查。完整流程还可以放进<a href="/ai-visual-creation-handbook/ecommerce/cross-border-canvas">三类画布</a>。</p><h2 id="最小完成标准" tabindex="-1">最小完成标准 <a class="header-anchor" href="#最小完成标准" aria-label="Permalink to &quot;最小完成标准&quot;">​</a></h2><p>一张图能对照真实商品核验；对应渠道位置明确；准确文字与单位无误；文件能打开且裁切适用。规划、生成、合成、源文件与后台上传各自记录完成状态。当前内容完成的是教程和模板，不是新商品实操结果。</p>',20)])])}const b=a(d,[["render",i]]);export{m as __pageData,b as default};
